# -*- coding: utf-8 -*-
"""Builds process_test.sql: end-to-end process tests that run on the real database
inside one DO block and roll everything back at the end (nothing is saved, no notifications remain).
The report comes back as the error message of the final RAISE, which is what forces the rollback."""
import sys
L = []
def out(s): L.append(s)
def AS(u): return f"perform pg_temp.u({u});"
SYS = "perform pg_temp.u(null);"
def esc(s): return s.replace("'", "''")
def line(name, cond, detail="err"):
    out(f"  rep := rep || pg_temp.r('{esc(name)}', ({cond}), ({detail})::text);")
def H(title): out(f"  rep := rep || E'\\n' || '{esc(title)}' || E'\\n';")
def ACT(u, stmt, name, ok=True):
    """run stmt as user u; ok=True expects success, ok=False expects it to be blocked"""
    out(f"  {AS(u)}")
    out(f"  begin {stmt}; okv := true; err := null; exception when others then okv := false; err := sqlerrm; end;")
    out(f"  {SYS}")
    line(name, "okv" if ok else "not okv", "err" if ok else "'לא נחסם'")
def SEE(u, query, var):
    out(f"  {AS(u)}")
    out(f"  {query} into {var};")
    out(f"  {SYS}")
def S(stmt): out(f"  {stmt};")
def C(name, cond, detail="null"): line(name, cond, detail)

# ---------------- setup ----------------
out("""create or replace function pg_temp.u(x uuid) returns void language plpgsql as $f$ begin
 perform set_config('app.bypass','',true);
 if x is null then perform set_config('role','none',true); perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','',true);
 else perform set_config('role','authenticated',true); perform set_config('request.jwt.claim.sub',x::text,true);
  perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true); end if; end $f$;
create or replace function pg_temp.r(nm text, c boolean, d text) returns text language sql as $f$
 select case when c then '✓ '||nm else '✗ '||nm||' ['||coalesce(d,'')||']' end || E'\\n' $f$;""")
out("do $test$")
out("declare rep text := ''; nfail int := 0; ntot int := 0; okv boolean; err text; n int; t text; j jsonb;")
out("  u_admin uuid := gen_random_uuid(); u_gal uuid := gen_random_uuid(); u_art uuid := gen_random_uuid(); u_win uuid := gen_random_uuid();")
out("  u_win2 uuid := gen_random_uuid(); u_prn uuid := gen_random_uuid(); u_cust uuid := gen_random_uuid(); u_cust2 uuid := gen_random_uuid();")
out("  u_cur uuid := gen_random_uuid(); u_inv uuid := gen_random_uuid(); u_app uuid := gen_random_uuid(); u_app2 uuid := gen_random_uuid(); u_dir uuid := gen_random_uuid(); u_dir2 uuid := gen_random_uuid();")
out("  o_gal uuid; o_win uuid; o_win2 uuid; o_prn uuid; a_id uuid; slug text := 'pt' || substr(md5(random()::text),1,8);")
out("  w1 bigint; w2 bigint; w3 bigint; wine1 bigint; d1 bigint; d2 bigint; d3 bigint; d4 bigint; d5 bigint; co1 bigint; tok text; ph text; ph2 text; app1 bigint; app2 bigint; r1 bigint; old_prn uuid; sid bigint; dco1 bigint; dco2 bigint; dco3 bigint; vcode text; ds jsonb;")
out("begin")
S("perform set_config('app.bypass','',true)")
